<?php
namespace App\Http\Controllers\POS;
use App\Http\Controllers\Controller;use App\Models\InventoryItem;use App\Services\Inventory\InventoryService;use Illuminate\Http\Request;use RuntimeException;
class InventoryController extends Controller{public function index(Request $r){$pid=$r->user()->property_id;$items=InventoryItem::with(['movements'=>fn($q)=>$q->latest()->limit(5)])->where('property_id',$pid)->orderBy('name')->get();$low=$items->filter(fn($i)=>(float)$i->quantity_on_hand<=(float)$i->reorder_level)->count();return view('pos.inventory',compact('items','low'));}public function store(Request $r){$d=$r->validate(['sku'=>'required|max:50','name'=>'required|max:150','category'=>'nullable|max:100','kind'=>'required|in:food,beverage,ingredient,supply,other','unit'=>'required|max:30','quantity_on_hand'=>'nullable|numeric|min:0','reorder_level'=>'nullable|numeric|min:0','average_cost'=>'nullable|numeric|min:0']);InventoryItem::create(['property_id'=>$r->user()->property_id]+$d+['is_active'=>true]);return back()->with('success','Inventory item created.');}public function adjust(Request $r,InventoryItem $item,InventoryService $svc){abort_unless($item->property_id===$r->user()->property_id,404);$d=$r->validate(['quantity'=>'required|numeric|not_in:0','type'=>'required|in:opening,purchase,adjustment,wastage,breakage,return','notes'=>'nullable|max:500']);try{$svc->adjust($item,(float)$d['quantity'],$d['type'],$r->user()->id,$d['notes']??null);return back()->with('success','Stock updated.');}catch(RuntimeException $e){return back()->withErrors(['stock'=>$e->getMessage()]);}}}
